/* Local-file transport adapter. Original reader HTML/CSS/JS otherwise stay unchanged. */
(() => {
 'use strict';
 const originalFetch=window.fetch.bind(window),base=new URL('local-content/',document.currentScript.src),cache=new Map();
 const get=path=>{const url=new URL(path,base).href;if(!cache.has(url))cache.set(url,originalFetch(url).then(r=>{if(!r.ok)throw Error('Missing local content: '+path);return r.json();}));return cache.get(url);};
 const meta=()=>get('manifest.json');
 const value=(row,key)=>key.startsWith('/')?key.slice(1).split('/').reduce((v,k)=>v?.[k.replace(/~1/g,'/').replace(/~0/g,'~')],row):row[key];
 function matches(row,f){const v=value(row,f.field),t=f.value;switch(f.op){case'eq':return v===t;case'ne':return v!==t;case'in':return t.includes(v);case'exists':return Object.hasOwn(row,f.field);case'is_missing':return !Object.hasOwn(row,f.field);case'is_null':return v==null;case'contains':return v?.includes?.(t)||false;case'starts_with':return typeof v==='string'&&v.startsWith(t);case'lt':return v!=null&&v<t;case'lte':return v!=null&&v<=t;case'gt':return v!=null&&v>t;case'gte':return v!=null&&v>=t;default:throw Error('Unsupported local filter: '+f.op);}}
 async function envelopes(name,keys){const m=await meta(),t=m.tables[name];if(!t)throw Error('Unmigrated local table: '+name);if(keys&&t.shards){const paths=await Promise.all([...new Set(keys)].map(async key=>{const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key));return [...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('').slice(0,2);}));const pieces=await Promise.all([...new Set(paths)].filter(p=>t.shards.includes(p)).map(p=>get('shards/'+name+'/'+p+'.json')));return pieces.flat();}return get('tables/'+name+'.json');}
 async function select(name,args={}){let rows=(await envelopes(name,args.keys)).filter(r=>args.include_deleted||!r.deleted);if(args.keys){const keys=new Set(args.keys);rows=rows.filter(r=>keys.has(r.key));}if(args.filters?.length)rows=rows.filter(r=>args.filter_mode==='any'?args.filters.some(f=>matches(r.row,f)):args.filters.every(f=>matches(r.row,f)));if(args.text_search){const s=args.text_search,query=s.case_sensitive?s.query:s.query.toLowerCase(),terms=s.term_mode==='phrase'?[query]:query.split(/\s+/);rows=rows.filter(r=>{let text=s.fields.map(k=>String(value(r.row,k)??'')).join(' ');if(!s.case_sensitive)text=text.toLowerCase();return s.term_mode==='any'?terms.some(t=>text.includes(t)):terms.every(t=>text.includes(t));});}rows.sort((a,b)=>a.key<b.key?-1:a.key>b.key?1:0);for(const order of [...(args.order_by||[])].reverse())rows.sort((a,b)=>{const av=value(a.row,order.field),bv=value(b.row,order.field);const c=av==null?(bv==null?0:1):bv==null?-1:av<bv?-1:av>bv?1:0;return order.direction==='desc'?-c:c;});if(args.select)rows=rows.map(r=>({...r,row:Object.fromEntries(args.select.filter(k=>Object.hasOwn(r.row,k)).map(k=>[k,r.row[k]]))}));return rows;}
 async function query(args){const m=await meta(),name=args.path.split('/').pop(),t=m.tables[name];if(!t)throw Error('Unmigrated local table: '+name);if(args.view?.revision&&args.view.revision!==m.revision)throw Error('Local content changed; refresh.');const all=await select(name,args),offset=args.offset||0,limit=args.limit??100,rows=all.slice(offset,offset+limit);return {repo:args.repo,path:args.path,revision:m.revision,definition:t.definition,row_count:t.count,matched_count:all.length,returned_count:rows.length,deleted_count:0,offset,limit,rows,truncated:offset+rows.length<all.length,source_kind:'local_ccn_content'};}
 const cell=v=>v==null?{type:'null'}:typeof v==='number'?{type:Number.isInteger(v)?'integer':'real',value:v}:{type:'text',value:String(v)};
 async function relation(args){const m=await meta(),data=new Map(),bindings=[];for(const b of args.bindings){if(b.revision&&b.revision!==m.revision)throw Error('Local relation revision changed');const rows=await select(b.path.split('/').pop(),b.source_query||{});data.set(b.alias,rows);bindings.push({...b,revision:m.revision,include_deleted:false});}const sql=args.sql||'';let columns,raw=[];
  if(/^SELECT\s+'[^']+'\s+AS\s+kind,/i.test(sql)){columns=['kind','key','row_version','row_json'];for(const term of sql.split(/\s+UNION ALL\s+/i)){const part=/^SELECT\s+'([^']+)'\s+AS\s+kind,key,row_version,row_json\s+FROM\s+(\w+)$/i.exec(term.trim());if(!part||!data.has(part[2]))throw Error('Unsupported local semantic relation');for(const r of data.get(part[2]))raw.push([part[1],r.key,r.row_version,JSON.stringify(r.row)]);}}
  else if(sql.includes('GROUP BY f.key')&&args.bindings.length===3){columns=['key','row_version','row_json'];const [f,c,links]=args.bindings.map(b=>data.get(b.alias)),rank=new Map();for(const link of links){const channel=c.find(r=>r.row.channel_id===link.row.channel_id&&r.row.enabled);if(!channel)continue;const id=link.row.family_id,old=rank.get(id)||[Infinity,Infinity];rank.set(id,[Math.min(old[0],channel.row.priority==='P0'?0:1),Math.min(old[1],link.row.position)]);}const limit=Number(/LIMIT\s+(\d+)/i.exec(sql)?.[1]||20);const result=f.filter(r=>rank.has(r.key)).sort((a,b)=>rank.get(a.key)[0]-rank.get(b.key)[0]||rank.get(a.key)[1]-rank.get(b.key)[1]||(a.key<b.key?-1:1)).slice(0,limit);raw=result.map(r=>[r.key,r.row_version,JSON.stringify(r.row)]);}
  else if(sql.startsWith('WITH matched AS ')&&args.bindings.length===2){columns=['item_key','pipeline_json','source_json','total'];const [pipeline,sources]=args.bindings.map(b=>data.get(b.alias)),lookup=new Map(sources.map(r=>[r.key,r]));let matched=pipeline.map(r=>({p:r,s:lookup.get(r.row.source_id)}));if(sql.includes('WHERE s.key IS NOT NULL'))matched=matched.filter(r=>r.s);matched.sort((a,b)=>a.p.row.priority-b.p.row.priority||(a.p.key<b.p.key?-1:1));const [limit,offset]=(args.parameters||[]).map(p=>p.value),page=matched.slice(offset,offset+limit);raw=page.map(r=>[r.p.key,JSON.stringify(r.p.row),r.s?JSON.stringify(r.s.row):null,matched.length]);if(!page.length)raw=[[null,null,null,matched.length]];}
  else throw Error('Unsupported local read relation');
  const limit=args.limits?.max_result_rows||1000,truncated=raw.length>limit,rows=raw.slice(0,limit).map(r=>r.map(cell)),output_bytes=new TextEncoder().encode(JSON.stringify(rows)).length;if(output_bytes>(args.limits?.max_result_bytes||2097152))throw Error('Local result budget exceeded');return {revision:m.revision,bindings,columns,rows,truncated,output_bytes,source_kind:'local_ccn_content'};
 }
 async function call(name,args){if(name==='skill_get')return {outcome:'loaded',skill:{summary:{skill_id:'table.query',skill_version:'2.3.0'},operations:[{name:args.operation||'table_query',access_lane:'read'}]}};if(name!=='skill_run_read'||args.skill_id!=='table.query')throw Error('Only local content reads are supported');let result;const operation=args.operation,a=args.arguments;if(operation==='table_query')result=await query(a);else if(operation==='table_relation_query')result=await relation(a);else if(operation==='table_status'){const m=await meta(),t=m.tables[a.path.split('/').pop()];if(!t)throw Error('Unmigrated table');result={repo:a.repo,path:a.path,definition:t.definition,revision:m.revision,row_count:t.count,deleted_count:0,source_kind:'local_ccn_content'};}else throw Error('Unsupported local read operation: '+operation);return {outcome:'executed',skill_id:'table.query',skill_version:'2.3.0',operation,result};}
 window.fetch=async(input,options={})=>{const target=new URL(typeof input==='string'?input:input.url,location.href);if(target.origin!==location.origin||target.pathname!=='/mcp')return originalFetch(input,options);let request;try{request=JSON.parse(options.body);if(request.method!=='tools/call')throw Error('Only local reads are supported');const v=await call(request.params.name,request.params.arguments||{});return new Response(JSON.stringify({jsonrpc:'2.0',id:request.id,result:{structuredContent:v,content:[{type:'text',text:JSON.stringify(v)}]}}),{headers:{'Content-Type':'application/json'}});}catch(error){return new Response(JSON.stringify({jsonrpc:'2.0',id:request?.id,result:{isError:true,structuredContent:{outcome:'error',error:{code:'local_read_failed',message:error.message}},content:[]}}),{headers:{'Content-Type':'application/json'}});}};
})();
